    menu_add_option(1, "4:3");
    menu_add_option(2, "16:10");
    menu_add_option(3, "16:9");
    menu_add_option(4, "2:1");

    menu_addedit_select("Framerate:", "global.frameratekind", menu_engine_options_framerate);
    menu_add_option(0, "30");
    menu_add_option(1, "60");

    menu_addedit_select("V Sync:", "global.monitorSync", menu_engine_options_v_sync);
